///|
fn polynomial(terms : Array[(Int32, Array[Int32])]) -> @poly.Polynomial {
  @poly.polynomial(@oracle.nat(3), @oracle.chain(terms.map(fn(t) {
    @poly.Term::{coefficient: @oracle.rational(t.0, 1), exponents: @oracle.chain(t.1.map(@oracle.nat))}
  }))).unwrap()
}

///|
fn main {
  // The original optional quadratic-in-z stress from the independent review.
  // x=0, y=1, x*z^2+y*z-z-1=0 is UNSAT by direct substitution.
  let source = @qf.Conjunction(
    @qf.Atom(polynomial([(1, [1, 0, 0])]), @qf.EqualZero),
    @qf.Conjunction(
      @qf.Atom(polynomial([(1, [0, 1, 0]), (-1, [0, 0, 0])]), @qf.EqualZero),
      @qf.Atom(polynomial([(1, [1, 0, 2]), (1, [0, 1, 1]), (-1, [0, 0, 1]), (-1, [0, 0, 0])]), @qf.EqualZero),
    ),
  )
  println("prepare")
  let problem = @cad.prepare(@oracle.nat(3), source).unwrap()
  println("search")
  let mut state = @cad.start_search(problem)
  for _ in 0..<100000 {
    match @cad.search_step(state).unwrap() {
      @cad.Paused(next) => state = next
      @cad.Satisfiable(_) => abort("closed-form UNSAT returned SAT")
      @cad.Unsatisfiable(value) => {
        println("check")
        if !@cad.check_result(problem, value, @cad.certificate(value)) {
          abort("invalid certificate")
        }
        println("UNSAT checked")
        return
      }
    }
  }
  abort("transition budget exhausted; no answer inferred")
}
